/**
 * Alert pipeline (Phase 12, spec 7.2). One background job: /api/cron/check-alerts every 5 minutes (external
 * scheduler) runs checkAllAlerts(); garden pages also run syncGarden() with a 60 s cache.
 *   - Gardens are grouped by rounded point (2 decimals): NWS once per point, Open-Meteo hourly once per point.
 *   - New or updated alerts (dedupe by NWS id + sent) are stored, tasks are generated by lib/engine/alertTasks.ts
 *     (Gemini may reword them, same count and order), and Web Push goes to the garden's subscribers.
 *   - Alerts that are no longer active are marked inactive; their open tasks close with "Alert ended" and
 *     follow-up tasks are added.
 */
import { rewriteTasks } from "./ai/features";
import { getAlerts } from "./clients/nws";
import { getHourly } from "./clients/openmeteo";
import { getStorms, nearbyStorms } from "./clients/nhc";
import { prisma } from "./db";
import { getGarden, getPlants } from "./data";
import { getEco } from "./eco";
import { alertTasks, dedupeKey, followUpTasks, isHeavyRain, rainNext24h, ruleFor, type AlertCtx } from "./engine/alertTasks";
import { harvestWindow } from "./engine/edibles";
import { rainGardenGal, roofInflowGal } from "./engine/eco/rain";
import { yearsBetween } from "./engine/geo";
import { heightAt, mean } from "./engine/growth";
import type { Prisma } from "./generated/prisma/client";
import { sendPush } from "./push";
import type { GardenDoc, NwsAlert, Plant } from "./types";

export interface IncomingAlert {
  source: "nws" | "openmeteo" | "sample";
  external_id: string;
  sent: string | null;
  event: string;
  severity?: string | null;
  urgency?: string | null;
  certainty?: string | null;
  headline: string;
  instruction?: string | null;
  onset?: string | null;
  ends?: string | null;
  is_sample?: boolean;
  raw?: unknown;
}

const iso = (d: Date | null | undefined) => (d ? d.toISOString() : null);
const todayEt = () => new Date().toLocaleDateString("en-CA", { timeZone: "America/New_York" });

/** Plant names by role for plant-specific task wording, plus the Sustainable section's barrel and rain garden. */
async function ctxFor(g: GardenDoc, plants: Plant[], now: string, rainMm = 50): Promise<AlertCtx> {
  const byId = new Map(plants.map((p) => [p.id, p]));
  const today = todayEt();
  const placed = g.placements.map((p) => ({ p, plant: byId.get(p.plant_id) })).filter((x): x is { p: typeof x.p; plant: Plant } => !!x.plant);
  const age = (x: (typeof placed)[number]) => yearsBetween(x.p.planted_on, today);
  const uniq = (xs: string[]) => [...new Set(xs)];
  const eco = (await getEco(g.id).catch(() => null))?.eco;
  const roof = eco?.house ? eco.roof_sqft ?? eco.house.w * eco.house.h : 0;
  return {
    now, balcony: g.site.kind === "balcony",
    young_trees: uniq(placed.filter((x) => x.plant.woody && mean(x.plant.mature_height_ft) >= 10 && age(x) < 3).map((x) => x.plant.common_name)),
    tall: uniq(placed.filter((x) => heightAt(x.plant, age(x)) >= 4).map((x) => x.plant.common_name)),
    tender: uniq(placed.filter((x) => x.plant.cold_hardy_f >= 30).map((x) => x.plant.common_name)),
    edibles: uniq(placed.filter((x) => x.plant.edible).map((x) => x.plant.common_name)),
    ripe: uniq(placed.filter((x) => x.plant.edible && (() => { const w = harvestWindow(x.plant.edible!, x.p.planted_on); return w.start <= today && w.end >= today; })()).map((x) => x.plant.common_name)),
    barrel_gal: eco?.barrel_gal || undefined,
    barrel_fill_gal: roof ? roofInflowGal(roof, [{ month: 1, rain_mm: rainMm, et0_mm: 0 }])[0] : undefined,
    rain_garden_gal: eco?.rain_garden_sqft ? rainGardenGal(eco.rain_garden_sqft) : undefined,
  };
}

/** Store one alert for a garden (if new), create its tasks, push. Returns null when the event has no rule or it's a duplicate. */
export async function ingest(g: GardenDoc, plants: Plant[], a: IncomingAlert, opts: { push?: boolean } = {}) {
  if (!ruleFor(a.event)) return null;
  const key = dedupeKey(a.external_id, a.sent);
  const exists = await prisma.alert.findUnique({ where: { garden_id_dedupe_key: { garden_id: g.id, dedupe_key: key } } });
  if (exists) return null;
  const now = new Date().toISOString();
  // An updated version of the same alert replaces the old one (its open tasks are regenerated).
  const older = await prisma.alert.findMany({ where: { garden_id: g.id, external_id: a.external_id, active: true } });
  for (const o of older) {
    await prisma.alert.update({ where: { id: o.id }, data: { active: false } });
    await prisma.task.updateMany({ where: { alert_id: o.id, done: false, closed_reason: null }, data: { closed_reason: "Alert updated" } });
  }
  const rules = alertTasks({ event: a.event, onset: a.onset, ends: a.ends }, await ctxFor(g, plants, now))!;
  // Gemini may reword the tasks (never the safety line); same count and order or the rule text stays.
  const body = rules.tasks.filter((t) => t.kind !== "safety");
  const rw = await rewriteTasks(body.map((t) => ({ when: "", text: t.title })), `${a.event}: ${a.headline}`);
  const words = new Map(body.map((t, i) => [t, rw.steps[i]?.text ?? t.title]));
  const alert = await prisma.alert.create({
    data: {
      garden_id: g.id, source: a.source, external_id: a.external_id, dedupe_key: key, sent: a.sent ? new Date(a.sent) : null,
      event: a.event, severity: a.severity ?? null, urgency: a.urgency ?? null, certainty: a.certainty ?? null, headline: a.headline,
      instruction: a.instruction ?? null, onset: a.onset ? new Date(a.onset) : null, ends: a.ends ? new Date(a.ends) : null,
      is_sample: !!a.is_sample, raw: (a.raw ?? null) as Prisma.InputJsonValue,
      tasks: {
        create: rules.tasks.map((t, i) => ({
          garden_id: g.id, kind: t.kind, title: t.kind === "safety" ? t.title : words.get(t) ?? t.title, detail: t.detail ?? null,
          due_at: new Date(t.due_at), priority: t.priority, source: "alert", position: i,
        })),
      },
    },
  });
  if (opts.push !== false) {
    const first = body[0] ? words.get(body[0]) : null;
    await sendPush(g.id, {
      title: `${a.event}${a.is_sample ? " (sample)" : ""}`, tag: alert.id, url: `/garden/${g.id}/alerts`,
      body: [first, rules.safety].filter(Boolean).join(" · ").slice(0, 180),
    }).catch((e) => console.warn("[alerts] push failed", e));
  }
  return alert;
}

/** Mark alerts inactive, close their open tasks and add follow-ups. */
export async function endAlerts(g: GardenDoc, ids: string[]) {
  const now = new Date().toISOString();
  for (const id of ids) {
    const a = await prisma.alert.findUnique({ where: { id } });
    if (!a?.active) continue;
    await prisma.alert.update({ where: { id }, data: { active: false } });
    await prisma.task.updateMany({ where: { alert_id: id, done: false, closed_reason: null }, data: { closed_reason: "Alert ended" } });
    const follow = followUpTasks({ event: a.event }, now, g.site.kind === "balcony");
    if (follow.length) {
      await prisma.task.createMany({ data: follow.map((t, i) => ({ garden_id: g.id, alert_id: id, kind: t.kind, title: t.title, due_at: new Date(t.due_at), priority: t.priority, source: "followup", position: 100 + i })) });
    }
  }
}

function fromNws(a: NwsAlert): IncomingAlert {
  return {
    source: "nws", external_id: a.id ?? `nws:${a.event}:${a.headline}`, sent: a.sent ?? null, event: a.event, severity: a.severity, urgency: a.urgency,
    certainty: a.certainty, headline: a.headline, instruction: a.instruction, onset: a.onset, ends: a.ends, raw: { url: a.url ?? null, description: a.description?.slice(0, 2000) ?? null },
  };
}

/** Sync one point's live sources into each garden at that point. */
async function syncGardens(gardens: GardenDoc[], plants: Plant[], nws: NwsAlert[], hourly: { time: string; precip_mm: number }[]) {
  const now = new Date().toISOString();
  const incoming = nws.filter((a) => ruleFor(a.event)).map(fromNws);
  // Heavy rain without an NWS alert: ≥ 50 mm forecast in the next 24 h (one alert per day).
  const coveredByNws = incoming.some((a) => /flood|hurricane|tropical/i.test(a.event));
  if (!coveredByNws && isHeavyRain(hourly, now)) {
    const mm = rainNext24h(hourly, now);
    incoming.push({ source: "openmeteo", external_id: `openmeteo:heavy_rain:${now.slice(0, 10)}`, sent: null, event: "Heavy rain", severity: "Moderate",
      headline: `Heavy rain forecast: about ${(mm / 25.4).toFixed(1)} in in the next 24 hours`, onset: now, ends: new Date(Date.now() + 24 * 3600e3).toISOString(), raw: { mm } });
  }
  let created = 0;
  for (const g of gardens) {
    for (const a of incoming) if (await ingest(g, plants, a)) created++;
    // Live alerts that are no longer listed have ended; sample alerts end at their `ends` time.
    const keys = new Set(incoming.map((a) => a.external_id));
    const active = await prisma.alert.findMany({ where: { garden_id: g.id, active: true } });
    const ended = active.filter((a) => (a.source === "sample" ? !!a.ends && a.ends.toISOString() < now : !keys.has(a.external_id) || (!!a.ends && a.ends.toISOString() < now)));
    await endAlerts(g, ended.map((a) => a.id));
  }
  return created;
}

/** The cron job: every garden, grouped by rounded point. */
export async function checkAllAlerts() {
  const rows = await prisma.garden.findMany({ select: { id: true } });
  const plants = await getPlants();
  const gardens = (await Promise.all(rows.map((r) => getGarden(r.id)))).filter((g): g is GardenDoc => !!g);
  const points = new Map<string, GardenDoc[]>();
  for (const g of gardens) {
    const k = `${g.site.lat.toFixed(2)},${g.site.lon.toFixed(2)}`;
    points.set(k, [...(points.get(k) ?? []), g]);
  }
  let created = 0;
  for (const [, gs] of points) {
    const { lat, lon } = gs[0].site;
    const [nws, hourly] = await Promise.all([getAlerts(lat, lon), getHourly(lat, lon)]);
    created += await syncGardens(gs, plants, nws.alerts, hourly.hours);
  }
  const { storms } = await getStorms();
  return { gardens: gardens.length, points: points.size, created, storms: storms.length };
}

const lastSync = new Map<string, number>();
/** Page-load sync with a 60 s cache per garden. Errors never break the page. */
export async function syncGarden(g: GardenDoc): Promise<void> {
  const t = lastSync.get(g.id) ?? 0;
  if (Date.now() - t < 60_000) return;
  lastSync.set(g.id, Date.now());
  try {
    const [nws, hourly, plants] = await Promise.all([getAlerts(g.site.lat, g.site.lon), getHourly(g.site.lat, g.site.lon), getPlants()]);
    await syncGardens([g], plants, nws.alerts, hourly.hours);
  } catch (e) {
    console.warn("[alerts] sync failed", (e as Error).message);
  }
}

export interface AlertView {
  id: string; source: string; event: string; severity: string | null; headline: string; instruction: string | null; onset: string | null; ends: string | null;
  active: boolean; is_sample: boolean; created_at: string; url: string | null; safety: string | null;
  tasks: { id: string; kind: string; title: string; due_at: string; priority: string; done: boolean; closed_reason: string | null; source: string }[];
}

export async function alertViews(gardenId: string, opts: { activeOnly?: boolean; take?: number } = {}): Promise<AlertView[]> {
  const rows = await prisma.alert.findMany({
    where: { garden_id: gardenId, ...(opts.activeOnly && { active: true }) }, orderBy: [{ active: "desc" }, { created_at: "desc" }], take: opts.take ?? 30,
    include: { tasks: { orderBy: { position: "asc" } } },
  });
  return rows.map((a) => ({
    id: a.id, source: a.source, event: a.event, severity: a.severity, headline: a.headline, instruction: a.instruction, onset: iso(a.onset), ends: iso(a.ends),
    active: a.active, is_sample: a.is_sample, created_at: a.created_at.toISOString(), url: ((a.raw as { url?: string } | null)?.url) ?? null,
    safety: a.tasks.find((t) => t.kind === "safety")?.title ?? null,
    tasks: a.tasks.filter((t) => t.kind !== "safety").map((t) => ({ id: t.id, kind: t.kind, title: t.title, due_at: t.due_at.toISOString(), priority: t.priority, done: t.done, closed_reason: t.closed_reason, source: t.source })),
  }));
}

/** Open tasks from active alerts, in rule order (for "This week"). */
export async function openAlertTasks(gardenId: string) {
  const views = await alertViews(gardenId, { activeOnly: true });
  return views.flatMap((a) => a.tasks.filter((t) => !t.done && !t.closed_reason).map((t) => ({ id: t.id, title: t.title, due_at: t.due_at, priority: t.priority as "normal" | "urgent" })));
}

/** Tropical storms within 500 km (context banner only). */
export async function stormContext(lat: number, lon: number) {
  const { storms } = await getStorms().catch(() => ({ storms: [] }));
  return nearbyStorms(storms, lat, lon);
}
